inline void insert_snp_vv(haplotype_evdience_alloc* h, haplotype_evdience* a, uint64_t a_n, char misBase, UC_Read* g_read, void *km)
{
    if(a_n == 0) return;
    SnpStats *p = NULL; uint64_t /**nn = 0,**/ i;
    if(!km) kv_pushp(SnpStats, h->snp_stat, &p);
    else kv_pushp_km(km, SnpStats, h->snp_stat, &p);
    p->id = h->snp_stat.n-1;
    p->occ_0 = 1;
    p->occ_1 = 0;
    p->occ_2 = 0;
    p->overlap_num = 0;
    p->site = a[0].site;
    p->is_homopolymer = if_is_homopolymer_strict(p->site, g_read->seq, g_read->length);
    for (i = 0; i < a_n; i++) {
        if(a[i].type == 0) {
            a[i].overlapSite = p->id;
            h->snp_stat.a[p->id].occ_0 += a[i].cov;
        }
        else if(a[i].type == 1 && a[i].misBase == misBase) {
            a[i].overlapSite = p->id;
            h->snp_stat.a[p->id].occ_1 += a[i].cov;
        }
        else {
            h->snp_stat.a[p->id].occ_2 += a[i].cov;
        }
        h->snp_stat.a[p->id].overlap_num += a[i].cov;
    }
    h->snp_stat.a[p->id].score = -1;
}


int insert_snp_ee(haplotype_evdience_alloc* h, haplotype_evdience* a, uint64_t a_n, haplotype_evdience* u_a, UC_Read* g_read, void *km)
{
    uint64_t i, m, occ_0, occ_1[6], occ_2, diff;
    occ_0 = occ_2 = diff = 0; memset(occ_1, 0, sizeof(uint64_t)*6);

    for (i = 0; i < a_n; i++) {
        if(a[i].type == 0){
            occ_0 += a[i].cov;
        }else if(a[i].type == 1){
            occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]] += a[i].cov;
            diff += a[i].cov;
        }
        // else if(a[i].type == 2){
        //     occ_2++;
        //     diff++;
        // }
        occ_2 += a[i].cov;
    }

    /**
     1. if occ_0 = 0, that means all overlaps are different with this read at this site
     2. it is not possible that occ_1 = 0,
     3. if occ_1 = 1, there are only one difference. It must be a sequencing error.
        (for repeat, it maybe a snp at repeat. but ...)
    **/
    SnpStats *p = NULL; 
    uint32_t is_homopolymer = (uint32_t)-1; 
    if(occ_0 == 0 || diff <= 1) return 0;
    for (i = m = 0; i < 4; i++) {
        if(occ_1[i] >= 2){
            if(!km) kv_pushp(SnpStats, h->snp_stat, &p);
            else kv_pushp_km(km, SnpStats, h->snp_stat, &p);
            p->id = h->snp_stat.n-1;
            p->occ_0 = 1 + occ_0;
            p->occ_1 = occ_1[i];
            p->occ_2 = occ_2 - p->occ_0 - p->occ_1;
            p->overlap_num = 0;
            p->site = a[0].site;
            p->score = -1;
            p->overlap_num = occ_2;
            if(is_homopolymer == (uint32_t)-1) {
                is_homopolymer = if_is_homopolymer_strict(p->site, g_read->seq, g_read->length);
            }
            p->is_homopolymer = is_homopolymer;
            occ_1[i] = p->id;
            m++;
        } else {
            occ_1[i] = (uint64_t)-1;
        }
    }
    occ_1[4] = occ_1[5] = (uint64_t)-1;
    if(m == 0) return 0;
    
    for (i = m = 0; i < a_n; i++) {
        // fprintf(stderr, "[M::%s] a[%lu].misBase->%c\n", __func__, i, a[i].misBase);
        if(a[i].type == 0) {
            a[i].overlapSite = h->snp_stat.n-1;
        } else if(occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]]!=(uint64_t)-1){
            a[i].cov = a[i].overlapSite;///note: only renew cov here!!!
            a[i].overlapSite = occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]];
        } else {
            continue;
        }
        u_a[m++] = a[i];
    }

    /**
    // if(c_snp && ovlp) {
    //     ;
    // }
    for (i = m = 0; i < 4; i++) {
        if(occ_1[i] >= 2) {
            insert_snp_vv(h, a, a_n, s_H[i], g_read, km);
            m++;
        }
    }
    if(m == 0) return 0;

    for (i = m = 0; i < a_n; i++) {
        if(a[i].type == 0){
            u_a[m++] = a[i];
        }else if(a[i].type == 1){
            if(occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]] >= 2) u_a[m++] = a[i];
        }
    }
    **/

    return m;
}


uint8_t hpc_mask_ff(char *sa, int64_t sn, int64_t p, int64_t hpc_flk, int64_t hpc_rr, uint8_t *f, int64_t fn, int64_t fsift, int64_t hpc_cutoff, int64_t *hpc_s, int64_t *hpc_e)
{
    int64_t s = ((p>=hpc_flk)?(p-hpc_flk):0), e = (((p+hpc_flk)<=sn)?(p+hpc_flk):(sn)), k, r, rc, zs, ze; 

    for (r = 1; r <= hpc_rr; r++) {
        rc = r * hpc_cutoff/**HPC_CC**/;
        
        ///inlcuding p
        for (k = p + r; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++){;} ze = k; if(ze > e) {ze = e;} 
        for (k = p - 1; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--){;} zs = k + 1; if(zs < s) {zs = s;}
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            // fprintf(stderr, "-0-[M::%s] p::%ld, hh::[%ld,%ld), f::%u, %.*s\n", __func__, p, zs, ze, f?1:0, (int32_t)(ze - zs), sa + zs);
            if(f) {
                for (k = MAX(p, zs); (k < ze) && (k - fsift < fn); k++) {f[k - fsift] = 0;} f[p - fsift] = 0;
            }
            if(hpc_s) (*hpc_s) = zs; 
            if(hpc_e) (*hpc_e) = ze;
            return 1;
        } 

        ///do not inlcude p
        for (k = p + r + 1; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++); 
        zs = p + 1; if(zs < s) zs = s; ze = k; if(ze > e) ze = e; 
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            // fprintf(stderr, "-1-[M::%s] p::%ld, hh::[%ld,%ld), f::%u, %.*s\n", __func__, p, zs, ze, f?1:0, (int32_t)(ze - zs), sa + zs);
            if(f) {
                for (k = MAX(p, zs); (k < ze) && (k - fsift < fn); k++) {f[k - fsift] = 0;} f[p - fsift] = 0;
            }
            if(hpc_s) (*hpc_s) = zs; 
            if(hpc_e) (*hpc_e) = ze;
            return 1;
        }  

        ///inlcuding p
        for (k = p - r; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--){;} zs = k + 1; if(zs < s) {zs = s;} 
        for (k = p + 1; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++){;} ze = k; if(ze > e) {ze = e;} 
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            // fprintf(stderr, "-2-[M::%s] p::%ld, hh::[%ld,%ld), f::%u, %.*s\n", __func__, p, zs, ze, f?1:0, (int32_t)(ze - zs), sa + zs);
            if(f) {
                for (k = MAX(p, zs); (k < ze) && (k - fsift < fn); k++) {f[k - fsift] = 0;} f[p - fsift] = 0;
            }
            if(hpc_s) (*hpc_s) = zs; 
            if(hpc_e) (*hpc_e) = ze;
            return 1;
        } 

        ///do not inlcude p
        for (k = p - r - 1; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--); 
        zs = k + 1; if(zs < s) zs = s; ze = p; if(ze > e) ze = e; 
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            // fprintf(stderr, "-3-[M::%s] p::%ld, hh::[%ld,%ld), f::%u, %.*s\n", __func__, p, zs, ze, f?1:0, (int32_t)(ze - zs), sa + zs);
            if(f) {
                for (k = MAX(p, zs); (k < ze) && (k - fsift < fn); k++) {f[k - fsift] = 0;} f[p - fsift] = 0;
            }
            if(hpc_s) (*hpc_s) = zs; 
            if(hpc_e) (*hpc_e) = ze;
            return 1;
        } 
    }
    // fprintf(stderr, "-6-[M::%s] p::%ld, hh::[,), %.*s\n", __func__, p, (int32_t)(e - s), sa + s);
    return 0;
}

uint8_t hpc_mask_ff_region(char *sa, int64_t sn, int64_t s0, int64_t e0, int64_t hpc_flk, int64_t hpc_rr, int64_t hpc_cutoff, double hpc_rate)
{
    assert(e0>=s0);
    int64_t s = ((s0>=hpc_flk)?(s0-hpc_flk):0), e = (((e0+hpc_flk)<=sn)?(e0+hpc_flk):(sn)), k, r, rc, zs, ze, os, oe, ovlp; 

    for (r = 1; r <= hpc_rr; r++) {
        rc = r * (MAX(hpc_cutoff, hpc_rr));///hpc_cutoff = 6;
        
        ///inlcuding p
        for (k = ((e0>s0)?(e0-1):(e0))+r; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++){;} ze = k; if(ze > e) {ze = e;} 
        for (k = ((e0>s0)?(e0-1):(e0))-1; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--){;} zs = k + 1; if(zs < s) {zs = s;}
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            os = MAX(zs, s0); oe = MIN(ze, e0);
	        ovlp = ((oe>os)? (oe-os):0);
            if(e0 > s0) {
                if(ovlp > 0 && (ovlp >= ((e0 - s0)*hpc_rate))) return 1;///hpc_rate = 0.51
            } else {
                if(zs <= s0 && ze >= e0) return 1;
            }
        } 

        ///do not inlcude p
        if(e0 <= s0) {
            for (k = e0 + r + 1; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++); 
            zs = e0 + 1; if(zs < s) zs = s; ze = k; if(ze > e) ze = e; 
            if(((ze - zs) > r) && ((ze - zs) >= rc)) {
                // fprintf(stderr, "-1-[M::%s] p::%ld, hh::[%ld,%ld), f::%u, %.*s\n", __func__, p, zs, ze, f?1:0, (int32_t)(ze - zs), sa + zs);
                return 1;
            }  
        }

        ///inlcuding p
        for (k = s0 - r; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--){;} zs = k + 1; if(zs < s) {zs = s;} 
        for (k = s0 + 1; (k < e) && ((k-r) >= s) && (sa[k] == sa[k-r]); k++){;} ze = k; if(ze > e) {ze = e;} 
        if(((ze - zs) > r) && ((ze - zs) >= rc)) {
            os = MAX(zs, s0); oe = MIN(ze, e0);
	        ovlp = ((oe>os)? (oe-os):0);
            if(e0 > s0) {
                if(ovlp > 0 && (ovlp >= ((e0 - s0)*hpc_rate))) return 1;
            } else {
                if(zs <= s0 && ze >= e0) return 1;
            }
        } 

        ///do not inlcude p
        if(e0 <= s0) {
            for (k = s0 - r - 1; (k >= s) && ((k+r) < e) && (sa[k] == sa[k+r]); k--); 
            zs = k + 1; if(zs < s) zs = s; ze = s0; if(ze > e) ze = e; 
            if(((ze - zs) > r) && ((ze - zs) >= rc)) {
                return 1;
            } 
        }
    }
    // fprintf(stderr, "-6-[M::%s] p::%ld, hh::[,), %.*s\n", __func__, p, (int32_t)(e - s), sa + s);
    return 0;
}

int push_info(haplotype_evdience_alloc* h, haplotype_evdience* a, uint64_t a_n, haplotype_evdience* u_a, overlap_region *oa, asg8_v *v8, uint64_t tot_cov, uint64_t scw, uint64_t tcut)
{
    uint64_t i, k, m, occ_0, occ_1[6], occ_2, diff, rev_n; uint8_t ihpc = 0;
    occ_0 = occ_2 = diff = rev_n = 0; memset(occ_1, 0, sizeof(uint64_t)*6);

    
    radix_sort_haplotype_evdience_id_srt(a, a + a_n);
    for (k = 1, m = i = 0; k <= a_n; k++) {
        if((k == a_n) || (a[k].overlapID != a[m].overlapID)) {
            a[i] = a[m];
            // /**if(a[0].site == 3504)**/ {
            //     fprintf(stderr, "-%u-[M::%s-beg]\trid::%u\t%.*s\thh_tp::%u\n", a[0].site, __func__, 
            //         oa[a[i].overlapID].y_id, (int)Get_NAME_LENGTH(R_INF, oa[a[i].overlapID].y_id), Get_NAME(R_INF, oa[a[i].overlapID].y_id), hh_tp(a[i]));
            // }
            if(hh_tp(a[i]) == 0){
                occ_0 += a[i].cov;
                if((oa) && (oa[a[i].overlapID].y_pos_strand == 0)) {
                    rev_n += a[i].cov;
                }
                if((!ihpc) && (hh_hp(a[i]))) ihpc = 1;
            }else if(hh_tp(a[i]) == 1){
                occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]] += a[i].cov;
                diff += a[i].cov;
            }
            occ_2 += a[i].cov;

            i++; m = k;
        }
    }
    a_n = i;
    
    // for (i = 0; i < a_n; i++) {
    //     if(hh_tp(a[i]) == 0){
    //         occ_0 += a[i].cov;
    //         if((oa) && (oa[a[i].overlapID].y_pos_strand == 0)) {
    //             rev_n += a[i].cov;
    //         }
    //         if((!ihpc) && (hh_hp(a[i]))) ihpc = 1;
    //     }else if(hh_tp(a[i]) == 1){
    //         occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]] += a[i].cov;
    //         diff += a[i].cov;
    //     }
    //     occ_2 += a[i].cov;
    // }


    /**
     1. if occ_0 = 0, that means all overlaps are different with this read at this site
     2. it is not possible that occ_1 = 0,
     3. if occ_1 = 1, there are only one difference. It must be a sequencing error.
        (for repeat, it maybe a snp at repeat. but ...)
    **/
    SnpStats *p = NULL; 
    if(occ_0 == 0 || diff <= 1) return 0;
    if((oa) && (rev_n == occ_0)) return 0;
    if(!oa) {
        rev_n = occ_2;
    } else {
        rev_n++;
    }

    for (i = m = 0; i < 4; i++) {
        if(occ_1[i] >= 2){
            kv_pushp(SnpStats, h->snp_stat, &p);
            p->id = h->snp_stat.n-1;
            p->occ_0 = 1 + occ_0;
            p->occ_1 = occ_1[i];
            if((tot_cov > 0) && (tot_cov >= (p->occ_0 + p->occ_1))) {
                p->occ_2 = tot_cov - p->occ_0 - p->occ_1;
            } else {
                p->occ_2 = occ_2 + 1 - p->occ_0 - p->occ_1;
            }
            // fprintf(stderr, "[M::%s]\ttot_cov::%lu\tocc_2::%lu\n", __func__, tot_cov, occ_2);
            p->site = a[0].site;
            p->score = -1;
            p->overlap_num = rev_n;
            p->is_homopolymer = ihpc;
            occ_1[i] = p->id;
            m++;
            // fprintf(stderr, "[M::%s]\tsite::%u\tn0::%u\tn1::%u\n", __func__, p->site, p->occ_0, p->occ_1);
        } else {
            occ_1[i] = (uint64_t)-1;
        }
    }
    occ_1[4] = occ_1[5] = (uint64_t)-1;
    if(m == 0) return 0;
    
    if(!v8) {
        for (i = m = 0; i < a_n; i++) {
            // fprintf(stderr, "[M::%s] a[%lu].misBase->%c\n", __func__, i, a[i].misBase);
            if(hh_tp(a[i]) == 0) {
                a[i].overlapSite = h->snp_stat.n-1;
            } else if(occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]]!=(uint64_t)-1){
                a[i].cov = a[i].overlapSite;///note: only renew cov here!!!
                a[i].overlapSite = occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]];
            } else {
                continue;
            }
            u_a[m++] = a[i];
        }
    } else {
        uint64_t tpos, tqual, wqual;
        for (i = m = 0; i < a_n; i++) {
            tpos = a[i].overlapSite;
            if(hh_tp(a[i]) == 0) {
                a[i].overlapSite = h->snp_stat.n-1;
            } else if(occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]]!=(uint64_t)-1){
                a[i].cov = a[i].overlapSite;///note: only renew cov here!!!
                a[i].overlapSite = occ_1[seq_nt6_table[(uint8_t)(a[i].misBase)]];
            } else {
                continue;
            }
            tqual = wqual = 3;
            if(oa[a[i].overlapID].y_id < tcut) get_wqual(oa[a[i].overlapID].y_id, tpos, oa[a[i].overlapID].y_pos_strand, v8, NULL, scw, &tqual, &wqual);
            a[i].type |= (tqual<<2); a[i].type |= (wqual<<(sc_bn+2));
            // assert(hh_bq(a[i]) == tqual); assert(hh_wq(a[i]) == wqual); 
            // fprintf(stderr, "[M::%s] site::%u, type::%u, occ0::%lu, occ2::%lu, tqual::%lu, wqual::%lu\n", __func__, a[i].site, hh_tp(a[i]), occ_0, occ_2, tqual, wqual);
            u_a[m++] = a[i];
        }
    }
    

    return m;
}


void partition_overlaps_advance(overlap_region_alloc* overlap_list, All_reads* R_INF, 
                        UC_Read* g_read, UC_Read* overlap_read, Correct_dumy* dumy, 
                        haplotype_evdience_alloc* hap, int force_repeat)
{
    ResizeInitHaplotypeEvdience(hap);

    uint64_t k, l, m;
    long long window_start, window_end;
    long long num_availiable_win = 0;
    
    Window_Pool w_inf;
    init_Window_Pool(&w_inf, g_read->length, WINDOW, (int)(1.0/asm_opt.max_ov_diff_ec));

    int flag = 0;
    while(get_Window(&w_inf, &window_start, &window_end) && flag != -2)
    {
        dumy->length = 0;
        dumy->lengthNT = 0;
        ///return overlaps that is overlaped with [window_start, window_end]
        flag = get_available_interval(window_start, window_end, overlap_list, dumy);
        switch (flag)
        {
            case 1:    ///found matched overlaps
                break;
            case 0:    ///do not find any matched overlaps
                break;
            case -2: ///do not find any matched overlaps, and the next window also cannot match
                break;
        }
        
        num_availiable_win = num_availiable_win + dumy->length;
        
        ///need to deal with 
        cluster_advance(g_read->seq, window_start, window_end, overlap_list, dumy, R_INF, hap, overlap_read, 1);
    }

    ///very time-consuming
    ///Fix-attention ---> able to be sorted locally
    // qsort(hap->list, hap->length, sizeof(haplotype_evdience), cmp_haplotype_evdience);
    SetSnpMatrix(hap, &(hap->nn_snp), &(overlap_list->length), 0, NULL);
    for (k = 1, l = m = 0; k <= hap->length; ++k) {  
        if (k == hap->length || hap->list[k].site != hap->list[l].site) {
            m += insert_snp_ee(hap, hap->list+l, k-l, hap->list+m, g_read, NULL);
            l = k;
        }
    }
    hap->length = m;

    // generate_haplotypes_naive_advance(hap, overlap_list, NULL);
    generate_haplotypes_naive_HiFi(hap, overlap_list, 0.04, g_read, 1, 0, ((uint64_t)-1), asm_opt.s_hap_cov, asm_opt.infor_cov);
    // generate_haplotypes_DP(hap, overlap_list, R_INF, g_read->length, force_repeat);
    // generate_haplotypes_naive(hap, overlap_list, R_INF, g_read->length, force_repeat);

    lable_large_indels(overlap_list, g_read->length, dumy, asm_opt.max_ov_diff_ec);
}


