    //     fusion_merge();
    // }
    

    for (i = 0; i < on; i++) {
        assert((i<=0)||(ov[i].qs > ov[i-1].qe));
        sub_ciagar_gen(z, cl, ov[i].qs, ov[i].qe, wl, uref, hpc_g, rref, qstr, tu, exz, e_rate, ql, rid);
    }
    return on;
    // uint64_t i, qs = (uint64_t)-1, qe = (uint64_t)-1;
