///[s, e)
int64_t extract_sub_cigar_err_rr(overlap_region *z, int64_t s, int64_t e, ul_ov_t *p)
{
    int64_t wk = ovlp_cur_wid(*p), xk = ovlp_cur_xoff(*p), ck = ovlp_cur_coff(*p);
    int64_t min_w = ovlp_min_wid(*p), max_w = ovlp_max_wid(*p);//[min_w, max_w]
    bit_extz_t ez; window_list *m; int64_t bd = ovlp_bd(*p), s0, e0;
    s0 = ((int64_t)(z->w_list.a[min_w].x_start)) + bd; 
    e0 = ((int64_t)(z->w_list.a[max_w].x_end))+1-bd;
    if(s < s0) {s = s0;} if(e > e0) {e = e0;}///exclude boundary
    if(s >= e) return -1;

    int64_t ws, we, os, oe, ovlp, err = 0, xl, yl, werr, tot = e - s;
    if(wk < min_w || wk > max_w) wk = min_w;
    for (; wk >= min_w && z->w_list.a[wk].x_start > s; wk--); 
    if(wk < min_w || wk > max_w) return -1;
    for (; wk <= max_w && z->w_list.a[wk].x_end < s; wk++); 
    if(wk < min_w || wk > max_w) return -1;
    //s >= w_list.a[wk].x_start && s <= w_list.a[wk].x_end
    if(wk != ovlp_cur_wid(*p)) {//xk is global, while ck is local
        xk = z->w_list.a[wk].x_start; ck = 0;
    }

    while(wk <= max_w && z->w_list.a[wk].x_start < e) {///[s, e); [min_w, max_w]
        m = &(z->w_list.a[wk]); 
        ws = m->x_start; we = m->x_end+1;
        os = MAX(s, ws); oe = MIN(e, we);
        ovlp = ((oe>os)? (oe-os):0);
        
        if(ovlp) {
            xl = m->x_end+1-m->x_start;
            yl = m->y_end+1-m->y_start;
            if((is_ualn_win((*m))) || (is_est_aln((*m)))) {
                if(is_ualn_win((*m))) { //unmapped
                    werr = gen_err_unaligned(xl, yl);
                } else {
                    werr = m->error;//shared window
                }
                if(ovlp < xl) {
                    werr = (((double)ovlp)/((double)xl))*((double)werr);
                }
                //skip the whole window
                err += werr; xk = m->x_end+1; ck = m->clen;
            } else {
                if(ovlp == xl) {
                    //skip the whole window
                    err += m->error; xk = m->x_end+1; ck = m->clen;
                } else {
                    set_bit_extz_t(ez, (*z), wk); 
                    err += retrieve_cigar_err(&ez, os, oe, &xk, &ck);
                }                
            }
        }
        tot -= ovlp; 
        if(xk >= e) break;//[min_w, max_w] && [s, e)
        wk++; if(wk > max_w) break;
        xk = z->w_list.a[wk].x_start; ck = 0;//reset
    }
    assert(!tot);
    ovlp_cur_wid(*p) = wk; ovlp_cur_xoff(*p) = xk; ovlp_cur_coff(*p) = ck;
    return err;
}

///[s, e)
inline int64_t detect_near_cc_tlen(bit_extz_t *ez, int64_t ck0, int64_t xk0, int64_t yk0, uint8_t rev)
{
    int64_t ck = ck0, xk = xk0, yk = yk0, cn = ez->cigar.n, op;
    if(!rev) {
        if(ck >= cn) return yk;
        while (ck < cn) {
            op = ez->cigar.a[ck]>>14;
            if(op == 0) return yk;
            if(op!=2) xk += (ez->cigar.a[ck]&(0x3fff));
            if(op!=3) yk += (ez->cigar.a[ck]&(0x3fff)); 
            ck++; 
        }
    } else {
        if(ck <= 0) return yk;
        while (ck > 0) {
            --ck;
            op = ez->cigar.a[ck]>>14;
            if(op == 0) return yk;
            if(op!=2) xk -= (ez->cigar.a[ck]&(0x3fff));
            if(op!=3) yk -= (ez->cigar.a[ck]&(0x3fff)); 
        }
    }

    return yk;
}

inline int64_t cal0_ew(bit_extz_t *ez, int64_t ck, int64_t xk, int64_t s, int64_t e, int64_t max_e)
{
    int64_t cn = ez->cigar.n, err = 0, op, ol, ws, we, os, oe, ovlp;
    while (ck > 0 && xk > s) {
        --ck;
        if((ez->cigar.a[ck]>>14)!=2) xk -= (ez->cigar.a[ck]&(0x3fff));
    }

    while (ck < cn && xk < e && err <= max_e) {//[s, e)
        ws = xk; 
        op = ez->cigar.a[ck]>>14; ol = (ez->cigar.a[ck]&(0x3fff));
        if(op!=2) xk += ol;
        ck++; we = xk;
        if(!op) continue;

        if(op == 2) {
            if(ws > s && ws < e) err += ol;
            continue;
        }

        os = MAX(s, ws); oe = MIN(e, we);
        ovlp = ((oe>os)? (oe-os):0);
        err += ovlp;
    }

    return err;
}

///[s, e)
int64_t extract_sub_cigar_hc(overlap_region *z, All_reads *rref, haplotype_evdience_alloc* hp, char *qstr, uint64_t ql, UC_Read* tu, int64_t s, int64_t e, ul_ov_t *p, int64_t set_f, uint8_t *f, uint8_t occ_thres, uint64_t hpc_len, uint64_t h0_w)
{
    // fprintf(stderr, "\n[M::%s]\ts::%ld\te::%ld\tset_f::%ld\tovlp_id::%u\twid::%u\n", __func__, s, e, set_f, ovlp_id(*p), ovlp_cur_wid(*p));
    // if((!set_f) && (!ovlp_cur_ylen(*p))) return 1;///no potential informative site
    int64_t wk = ovlp_cur_wid(*p), xk = ovlp_cur_xoff(*p), yk = ovlp_cur_yoff(*p), ck = ovlp_cur_coff(*p), os, oe, sa0, ea0, t;
    bit_extz_t ez; int64_t bd = ovlp_bd(*p), s0, e0; char *ystr = NULL;
    s0 = ((int64_t)(z->w_list.a[wk].x_start)) + bd; 
    e0 = ((int64_t)(z->w_list.a[wk].x_end)) + 1 - bd;
    if(s < s0) {s = s0;} if(e > e0) {e = e0;}///exclude boundary
    if(s >= e) return -1;
    os = MAX(s, s0); oe = MIN(e, e0);
    if(oe <= os) return -1;

    set_bit_extz_t(ez, (*z), wk);
    if(!ez.cigar.n) return -1;
    int64_t cn = ez.cigar.n, op; int64_t ws, we, ovlp, xk0, yk0, ck0, yk1 = -1, /**xk1 = -1, ck1 = -1,**/ yl; haplotype_evdience ev; uint8_t om;
    xk0 = xk; yk0 = yk; ck0 = ck; ///for assertion
    if((ck < 0) || (ck > cn)) {//(*ck) == cn is allowed
        ck = 0; xk = ez.ts; yk = ez.ps;
    }
    
    while (ck > 0 && xk > s) {///x -> t; y -> p
        --ck;
        op = ez.cigar.a[ck]>>14;
        if(op!=2) xk -= (ez.cigar.a[ck]&(0x3fff));
        if(op!=3) yk -= (ez.cigar.a[ck]&(0x3fff)); 
    }
    
    if(set_f) {
        ovlp_cur_ylen(*p) = 0;
        xk0 = xk; yk0 = yk; ck0 = ck; 
    } else {
        assert(xk0 == xk); assert(yk0 == yk); assert(ck0 == ck);
        yk1 = yk0 + ovlp_cur_ylen(*p); yl = Get_READ_LENGTH((*rref), z->y_id);

        // UC_Read_resize(*tu, ovlp_cur_ylen(*p)); ystr = tu->seq; 
        // if(is_dbg) fprintf(stderr, "[M::%s] set_f::%ld, yk0::%ld, ovlp_cur_ylen::%u, ylen::%lu\n", __func__, set_f, yk0, ovlp_cur_ylen(*p), Get_READ_LENGTH((*rref), z->y_id));
        // recover_UC_Read_sub_region(ystr, yk0, ovlp_cur_ylen(*p), z->y_pos_strand, rref, z->y_id);
    }

    // if(is_dbg) fprintf(stderr, "---0---[M::%s] set_f::%ld, yk::%ld\n", __func__, set_f, yk);
     //some cigar will span s or e
    while (ck < cn && xk < e) {//[s, e)
        ws = xk; 
        op = ez.cigar.a[ck]>>14;
        if(op!=2) xk += (ez.cigar.a[ck]&(0x3fff));
        if(op!=3) yk += (ez.cigar.a[ck]&(0x3fff)); 
        ck++; we = xk;
        if(op != 0 && op != 1) continue;///only collect match/snp

        os = MAX(s, ws); oe = MIN(e, we);
        ovlp = ((oe>os)? (oe-os):0);
        if(!ovlp) continue;

        if(set_f) {
            if(op == 1) {
                for (t = os; t < oe; t++) {
                    f[t-s] = ((f[t-s]<=126)?(f[t-s]+1):(127));
                }
                // if(!hpc_len) {
                //     yk1 = oe-xk+yk;
                // } else {
                //     yk1 = yk; xk1 = xk; ck1 = ck;
                // } 
                yk1 = oe-xk+yk;
            }
        } else {
            if(op == 0) {
                for (t = os; t < oe; t++) {
                    if(f[t-s]) {
                        sa0 = t - h0_w; ea0 = t + h0_w;
                        ///r789
                        if(((sa0 >= ws) && (ea0 <= we)) || (cal0_ew(&ez, ck, xk, sa0, ea0, h0_w_p) <= h0_w_p)) {
                            om = ((f[t-s]==3)?1:0);
                            ev.misBase = qstr[t];
                            ev.overlapID = ovlp_id(*p);
                            ev.site = t;
                            ev.overlapSite = t-xk+yk;
                            ev.type = (om<<1);
                            ev.cov = 1;
                            addHaplotypeEvdience(hp, &ev, NULL);
                        }
                    }
                }
            } else if(op == 1) {
                for (t = os; t < oe; t++) {
                    if(f[t-s]) {
                        if(!ystr) {
                            // yk0 = ((hpc_len)?(detect_near_cc_tlen(&ez, ck, xk, yk, 1)):(t-xk+yk));
                            yk0 = t-xk+yk;
                            yk0 -= hpc_len; if(yk0 < 0) yk0 = 0;
                            UC_Read_resize(*tu, (yk1 - yk0)); ystr = tu->seq; 
                            recover_UC_Read_sub_region(ystr, yk0, (yk1 - yk0), z->y_pos_strand, rref, z->y_id);
                        }

                        om = ((f[t-s]==3)?1:0);
                        if((!om) && (hpc_len) && (hpc_mask_ff(ystr, yk1 - yk0, t-xk+yk-yk0, hpc_len, HPC_RR, NULL, -1, -1, HPC_CC, NULL, NULL))) om = 1;

                        ev.misBase = ystr[t-xk+yk-yk0];
                        ev.overlapID = ovlp_id(*p);
                        ev.site = t;
                        ev.overlapSite = t-xk+yk;
                        ev.type = (om<<1) + 1;
                        ev.cov = 1;
                        addHaplotypeEvdience(hp, &ev, NULL);
                        // if(ev.overlapID == 21 && ev.site == 17129) {
                        //     fprintf(stderr, "[M::%s]\ts::%ld\te::%ld\tck::%ld\txk::%ld\tyk::%ld\tset_f::%ld\n", __func__, s, e, ck, xk, yk, set_f);
                        // }
                    }

                }
            }
        }
    }
    // if(is_dbg) fprintf(stderr, "---1---[M::%s] set_f::%ld, yk::%ld\n", __func__, set_f, yk);

    if(set_f) {
        ovlp_cur_xoff(*p) = xk0; ovlp_cur_yoff(*p) = yk0; ovlp_cur_coff(*p) = ck0; 
        if(yk1 != -1) {
            // if((xk1 != -1) && (yk1 != -1)) {///detect nearby differences
            //     yk1 = detect_near_cc_tlen(&ez, ck1, xk1, yk1, 0);
            // }
            yk1 += hpc_len;
            yl = Get_READ_LENGTH((*rref), z->y_id);
            if(yk1 > yl) yk1 = yl;
            ovlp_cur_ylen(*p) = yk1 - yk0;
        } else {///no potential informative site; no second round
            ovlp_cur_ylen(*p) = 0;
        }
    } else {
        ovlp_cur_xoff(*p) = xk; ovlp_cur_yoff(*p) = yk; ovlp_cur_coff(*p) = ck; ovlp_cur_ylen(*p) = 0;
    }

    return 1;
}


int64_t extract_sub_err_hc(overlap_region *z, int64_t ql, int64_t s, int64_t e, ul_ov_t *p, int64_t *rerr)
{
    int64_t wk = ovlp_cur_wid(*p), xk = ovlp_cur_xoff(*p), yk = ovlp_cur_yoff(*p), ck = ovlp_cur_coff(*p), os, oe;
    bit_extz_t ez; int64_t s0, e0; (*rerr) = INT64_MAX;
    s0 = ((int64_t)(z->w_list.a[wk].x_start)); 
    e0 = ((int64_t)(z->w_list.a[wk].x_end)) + 1;
    if(s < s0) {s = s0;} if(e > e0) {e = e0;}///exclude boundary
    if(s >= e) return -1;
    os = MAX(s, s0); oe = MIN(e, e0);
    if(oe <= os) return -1;

    set_bit_extz_t(ez, (*z), wk);
    if(!ez.cigar.n) return -1;
    int64_t cn = ez.cigar.n, op; int64_t ws, we, ovlp; 
    if((ck < 0) || (ck > cn)) {//(*ck) == cn is allowed
        ck = 0; xk = ez.ts; yk = ez.ps;
    }
    
    while (ck > 0 && xk > s) {///x -> t; y -> p
        --ck;
        op = ez.cigar.a[ck]>>14;
        if(op!=2) xk -= (ez.cigar.a[ck]&(0x3fff));
        if(op!=3) yk -= (ez.cigar.a[ck]&(0x3fff)); 
    }
    
    //some cigar will span s or e
    (*rerr) = 0;
    while (ck < cn && xk < e) {//[s, e)
        ws = xk; 
        op = ez.cigar.a[ck]>>14;
        if(op!=2) xk += (ez.cigar.a[ck]&(0x3fff)); ///op == 3
        if(op!=3) yk += (ez.cigar.a[ck]&(0x3fff)); ///op == 2
        ck++; we = xk;

        os = MAX(s, ws); oe = MIN(e, we);
        ovlp = ((oe>os)? (oe-os):0);

        if(op != 2) {
            if(!ovlp) continue;
        } else {///ws == we
            if(ws < s || ws >= e) continue;
        }

        if(op == 1 || op == 3) {
            (*rerr) += ovlp;
        } else if(op == 2) {
            (*rerr) += (ez.cigar.a[ck-1]&(0x3fff));
        }
    }

    if((ck < cn) && (xk == e) && (e == ql)) {
        while (ck < cn) {//[s, e)
            op = ez.cigar.a[ck]>>14;
            if(op != 2) break;
            yk += (ez.cigar.a[ck]&(0x3fff)); ///op == 2
            (*rerr) += (ez.cigar.a[ck]&(0x3fff));
            ck++; 
        }
    }

    ovlp_cur_xoff(*p) = xk; ovlp_cur_yoff(*p) = yk; ovlp_cur_coff(*p) = ck; ovlp_cur_ylen(*p) = 0;
    return 1;
}


inline char* cal_hpc_len(All_reads *rref, uint8_t rev, uint32_t id, int64_t s0, int64_t e0, int64_t cs, int64_t ce, int64_t *rs, int64_t *re, UC_Read *z)
{
    int64_t os, oe, ol, cl; (*rs) = (*re) = -1;
    os = MAX(s0, cs); oe = MIN(e0, ce);
    if(os >= s0 && oe <= e0) {
        (*rs) = s0; (*re) = e0;
        return z->seq;
    }
    ol = oe - os; cl = ce - cs; (*rs) = cs; (*re) = ce;
    UC_Read_resize(*z, cl); 

    if((ol >= 16) || ((ol) && (ol > (cl * 0.75)))) {///reuse
        memmove(z->seq + os - cs, z->seq + os - s0, ol);
        if(os > cs) recover_UC_Read_sub_region(z->seq, cs, os - cs, rev, rref, id);
        if(ce > oe) recover_UC_Read_sub_region(z->seq + oe - cs, oe, ce - oe, rev, rref, id);
    } else {
        recover_UC_Read_sub_region(z->seq, cs, cl, rev, rref, id);
    }
    return z->seq;
}

